=== product-content.ts ===
export interface ProductFeature {
  icon: string;
  title: string;
  desc: string;
}

export interface ProductHighlight {
  label: string;
  value: string;
}

export interface ProductContent {
  purpose: string;
  features: ProductFeature[];
  highlights: ProductHighlight[];
  /** Real in-app screenshots to show in the product detail popup's gallery section. Empty/absent
   * until real images are supplied - the gallery falls back to placeholder slots until then. */
  screenshots?: string[];
}

export const PRODUCT_CONTENT: Record<string, ProductContent> = {
  HR: {
    purpose:
      'Replace scattered spreadsheets and manual approvals with one connected system for your entire employee lifecycle - from hiring to payroll to performance, all under a single login.',
    features: [
      { icon: 'fa-solid fa-id-card', title: 'Employee Records', desc: 'One master record per employee - profile, documents, department, and designation history.' },
      { icon: 'fa-solid fa-calendar-check', title: 'Attendance & Leave', desc: 'Daily attendance, leave requests and approvals, holidays, and shift schedules.' },
      { icon: 'fa-solid fa-money-check-dollar', title: 'Payroll & Compliance', desc: 'Salary structures, monthly payroll runs, loans, tax declarations, and full-and-final settlement.' },
      { icon: 'fa-solid fa-user-plus', title: 'Recruitment & Onboarding', desc: 'Job postings, interview scheduling, offer letters, and a guided onboarding checklist.' },
      { icon: 'fa-solid fa-chart-line', title: 'Performance Management', desc: 'KPI/KRA goals, configurable appraisal cycles, and performance ratings.' },
      { icon: 'fa-solid fa-plane-departure', title: 'Travel & Expenses', desc: 'Trip requests, approvals, advances, and expense settlement in one workflow.' }
    ],
    highlights: [
      { label: 'Pending Approvals', value: '3' },
      { label: 'On-time Attendance', value: '96%' },
      { label: 'Open Positions', value: '5' }
    ]
  },
  PP: {
    purpose:
      'Plan and track production the way your shop floor actually runs - schedules, capacity, and material flow in one place instead of manual logs and guesswork.',
    features: [
      { icon: 'fa-solid fa-calendar-days', title: 'Production Scheduling', desc: 'Plan jobs against real machine and shift capacity, not rough estimates.' },
      { icon: 'fa-solid fa-gauge-high', title: 'Capacity Planning', desc: 'See where your bottlenecks are before they cause delays.' },
      { icon: 'fa-solid fa-boxes-stacked', title: 'Material & Inventory Flow', desc: 'Track raw material consumption against each production run.' },
      { icon: 'fa-solid fa-clipboard-check', title: 'Quality & Output Tracking', desc: 'Log output, rejections, and rework against every batch.' }
    ],
    highlights: [
      { label: 'Active Jobs', value: '12' },
      { label: 'Capacity Used', value: '78%' },
      { label: 'On-time Delivery', value: '91%' }
    ]
  }
};

