namespace SubscriptionPortal.Core.Entities
{
    public class Tenant
    {
        public long Id { get; set; }

        /// <summary>
        /// The company's public, human-readable identifier - "TENANT001", "TENANT002", ... This is
        /// what identifies a customer everywhere outside the database: it is quoted in support, and
        /// it is the stable handle for "which company owns which provisioned product database"
        /// (see TenantDatabase). Unique across the portal; the numeric Id stays the internal key.
        ///
        /// <para>Null for the portal owner's own Tenant, which is not a customer and therefore has
        /// no tenant code - see the 2026-10-21 migration in the deployment script.</para>
        /// </summary>
        [StringLength(20)]
        public string? TenantCode { get; set; }

        [Required]
        [StringLength(200, MinimumLength = 2)]
        public string CompanyName { get; set; } = string.Empty;

        [Required]
        [StringLength(63, MinimumLength = 3)]
        [RegularExpression(@"^[a-z0-9](?:[a-z0-9-]{1,61}[a-z0-9])?$",
            ErrorMessage = "Subdomain must be 3-63 characters, lowercase letters/numbers/hyphens only, and cannot start or end with a hyphen.")]
        public string Subdomain { get; set; } = string.Empty;

        [Required]
        public TenantStatus Status { get; set; } = TenantStatus.Trial;

        public DateTime CreatedDate { get; set; } = DateTime.UtcNow;

        public DateTime? ModifiedDate { get; set; }

        public bool IsDeleted { get; set; }

        public ICollection<PortalUser> Users { get; set; } = new List<PortalUser>();

        public ICollection<Subscription> Subscriptions { get; set; } = new List<Subscription>();
    }
}

