=== PaymentService ===
using SubscriptionPortal.BusinessLogicLayer.Services.Payment.Interface;
using SubscriptionPortal.Core.CommonModels;
using SubscriptionPortal.Core.DTOs.Payment;
using SubscriptionPortal.Core.Enums;
using SubscriptionPortal.DataAccessLayer.Repositories.Payments.Interface;
using SubscriptionPortal.DataAccessLayer.Repositories.Subscriptions.Interface;
using PaymentEntity = SubscriptionPortal.Core.Entities.Payment;

namespace SubscriptionPortal.BusinessLogicLayer.Services.Payment.Implementation
{
    public class PaymentService : IPaymentService
    {
        private readonly ISubscriptionRepository _subscriptionRepository;
        private readonly IPaymentRepository _paymentRepository;
        private readonly IPaymentGatewayService _gateway;

        public PaymentService(
            ISubscriptionRepository subscriptionRepository,
            IPaymentRepository paymentRepository,
            IPaymentGatewayService gateway)
        {
            _subscriptionRepository = subscriptionRepository;
            _paymentRepository = paymentRepository;
            _gateway = gateway;
        }

        public async Task<ApiResponse<CreatePaymentOrderResponse>> CreateOrderAsync(long tenantId, CreatePaymentOrderRequest request)
        {
            var subscription = await _subscriptionRepository.GetSubscriptionWithPlanAsync(request.SubscriptionId);

            // Same "not found" message whether it doesn't exist or belongs to another tenant.
            if (subscription is null || subscription.TenantId != tenantId || subscription.Plan is null)
            {
                return ApiResponse<CreatePaymentOrderResponse>.Failure("Subscription not found.");
            }

            if (subscription.Status == SubscriptionStatus.Cancelled)
            {
                return ApiResponse<CreatePaymentOrderResponse>.Failure(
                    "This subscription has been cancelled and can no longer be paid for.");
            }

            if (!_gateway.IsConfigured)
            {
                return ApiResponse<CreatePaymentOrderResponse>.Failure(
                    "Online payments aren't available yet. Please check back soon.");
            }

            var amount = subscription.Plan.PricePerUser * subscription.Users;
            var payment = new PaymentEntity
            {
                SubscriptionId = subscription.Id,
                Amount = amount,
                Status = PaymentStatus.Created
            };
            await _paymentRepository.CreatePaymentAsync(payment);

            try
            {
                var order = await _gateway.CreateOrderAsync(amount, "INR", receipt: $"sub-{subscription.Id}-pay-{payment.Id}");

                return ApiResponse<CreatePaymentOrderResponse>.Success(new CreatePaymentOrderResponse
                {
                    RazorpayOrderId = order.OrderId,
                    RazorpayKeyId = string.Empty, // populated by the real gateway implementation once configured
                    AmountInPaise = order.AmountInPaise,
                    Currency = order.Currency,
                    PaymentId = payment.Id
                }, "Order created.");
            }
            catch (InvalidOperationException ex)
            {
                // Gateway isn't wired up yet - surface a clean message instead of a raw stack trace.
                return ApiResponse<CreatePaymentOrderResponse>.Failure(ex.Message);
            }
        }
    }
}
