        {
            throw new InvalidOperationException(
                "Online payments are not set up yet - Razorpay API keys have not been configured. " +
                "Add them to appsettings.json under \"Razorpay\" and register RazorpayPaymentGatewayService in Program.cs.");
        }

        public bool VerifyWebhookSignature(string payload, string signatureHeader)
        {
            throw new InvalidOperationException(
                "Online payments are not set up yet - Razorpay webhook verification is not implemented.");
        }
