using System.ComponentModel.DataAnnotations;

namespace SubscriptionPortal.Core.Entities
{
    public class PortalUser
    {
        public long Id { get; set; }

        /// <summary>Null until this person activates their first product (Try Demo/Subscribe) -
        /// Signup only creates the login itself, not a company/Tenant. See
        /// SubscriptionService.ActivateProductAsync, which creates the Tenant and attaches this
        /// user to it the moment they commit to a product.</summary>
        public long? TenantId { get; set; }

        public Tenant? Tenant { get; set; }

        [Required]
        [StringLength(150, MinimumLength = 2)]
        public string Name { get; set; } = string.Empty;

        [Required]
        [StringLength(256)]
        [EmailAddress]
        public string Email { get; set; } = string.Empty;

        [Required]
        [StringLength(20, MinimumLength = 7)]
        public string ContactNumber { get; set; } = string.Empty;

        [Required]
        [StringLength(256)]
        public string PasswordHash { get; set; } = string.Empty;

        /// <summary>FK to this Tenant's own RoleMaster row - the single source of truth for who
        /// this user is and what they can do (see Role/RolePageRight). Null alongside TenantId
        /// until this person activates their first product - there's no Role to assign before
        /// their Tenant (and its seeded Admin/User roles) exist.</summary>
        public long? RoleId { get; set; }

        public Role? Role { get; set; }

        public bool IsActive { get; set; } = true;

        /// <summary>
        /// Runs the PLATFORM itself - this portal, every company on it, and the catalog. Deliberately
        /// NOT the same thing as Role.IsSystem, which only means "runs my own company's portal
        /// logins". A customer who activates a product is the admin of the product database
        /// provisioned for them, never of this portal; without this separation their Tenant's
        /// seeded Admin role made them indistinguishable from the platform's own operators and
        /// they could see every other company's data.
        ///
        /// Granted and revoked from User Master by an existing platform owner - no role name, no
        /// email and no id is ever matched in code, so adding a business partner as a second owner
        /// is a checkbox, not a deployment.
        /// </summary>
        public bool IsPlatformOwner { get; set; }

        public DateTime CreatedDate { get; set; } = DateTime.UtcNow;

        public DateTime? LastLoginDate { get; set; }

        /// <summary>The company name typed at Signup, held here until it becomes a real Tenant.
        /// Null once TenantId is set (the Tenant's own CompanyName is authoritative from then on).</summary>
        [StringLength(200)]
        public string? PendingCompanyName { get; set; }
    }
}
