using SubscriptionPortal.BusinessLogicLayer.Services.Lifecycle.Interface;

namespace SubscriptionPortal.WebAPI.BackgroundServices
{
    /// <summary>
    /// Runs the trial lifecycle sweep once at startup, then once every 24 hours.
    /// Each run is isolated in its own DI scope since the lifecycle service/repository are scoped.
    /// </summary>
    public class TrialLifecycleBackgroundService : BackgroundService
    {
        private static readonly TimeSpan SweepInterval = TimeSpan.FromHours(24);

        private readonly IServiceScopeFactory _scopeFactory;
        private readonly ILogger<TrialLifecycleBackgroundService> _logger;

        public TrialLifecycleBackgroundService(IServiceScopeFactory scopeFactory, ILogger<TrialLifecycleBackgroundService> logger)
        {
            _scopeFactory = scopeFactory;
            _logger = logger;
        }

        protected override async Task ExecuteAsync(CancellationToken stoppingToken)
        {
            using var timer = new PeriodicTimer(SweepInterval);

            await RunSweepSafelyAsync(stoppingToken);

            try
            {
                while (await timer.WaitForNextTickAsync(stoppingToken))
                {
                    await RunSweepSafelyAsync(stoppingToken);
                }
            }
            catch (OperationCanceledException)
            {
                // Expected on shutdown.
            }
        }

        private async Task RunSweepSafelyAsync(CancellationToken stoppingToken)
        {
            try
            {
                using var scope = _scopeFactory.CreateScope();
                var lifecycleService = scope.ServiceProvider.GetRequiredService<ISubscriptionLifecycleService>();
                var result = await lifecycleService.RunDailySweepAsync();

                _logger.LogInformation(
                    "Trial lifecycle sweep complete: {ReadOnly} moved to ReadOnly, {Blocked} moved to Blocked, {Cancelled} moved to Cancelled.",
                    result.MovedToReadOnly, result.MovedToBlocked, result.MovedToCancelled);
            }
            catch (Exception ex) when (!stoppingToken.IsCancellationRequested)
            {
                _logger.LogError(ex, "Trial lifecycle sweep failed.");
            }
        }
    }
}
