﻿using System.Text;
using System.Text.Json.Serialization;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.EntityFrameworkCore;
using Microsoft.IdentityModel.Tokens;
using SubscriptionPortal.BusinessLogicLayer.Security;
using SubscriptionPortal.BusinessLogicLayer.Services.Account.Implementation;
using SubscriptionPortal.BusinessLogicLayer.Services.Account.Interface;
using SubscriptionPortal.BusinessLogicLayer.Services.Dashboard.Implementation;
using SubscriptionPortal.BusinessLogicLayer.Services.Dashboard.Interface;
using SubscriptionPortal.BusinessLogicLayer.Services.EmailConfigurations.Implementation;
using SubscriptionPortal.BusinessLogicLayer.Services.EmailConfigurations.Interface;
using SubscriptionPortal.BusinessLogicLayer.Services.Lifecycle.Implementation;
using SubscriptionPortal.BusinessLogicLayer.Services.Lifecycle.Interface;
using SubscriptionPortal.BusinessLogicLayer.Services.Notifications.Implementation;
using SubscriptionPortal.BusinessLogicLayer.Services.Notifications.Interface;
using SubscriptionPortal.BusinessLogicLayer.Services.Payment.Implementation;
using SubscriptionPortal.BusinessLogicLayer.Services.Payment.Interface;
using SubscriptionPortal.BusinessLogicLayer.Services.Provisioning.Implementation;
using SubscriptionPortal.BusinessLogicLayer.Services.Provisioning.Interface;
using SubscriptionPortal.BusinessLogicLayer.Services.RoleRights.Implementation;
using SubscriptionPortal.BusinessLogicLayer.Services.RoleRights.Interface;
