mkdir -p /home/rudy/docs/office/subscription_portal/BE/SubscriptionPortal.Core/Serialization && cat > /home/rudy/docs/office/subscription_portal/BE/SubscriptionPortal.Core/Serialization/UtcDateTimeJsonConverter.cs <<'EOF'
using System.Text.Json;
using System.Text.Json.Serialization;

namespace SubscriptionPortal.Core.Serialization
{
    /// <summary>
    /// Serializes every DateTime as explicit UTC, with the trailing "Z".
    ///
    /// <para>Every timestamp in this portal is already UTC - the DATETIME2 columns default to
    /// SYSUTCDATETIME() and the code writes DateTime.UtcNow - but DATETIME2 carries no offset, so
    /// EF Core hands the values back with Kind=Unspecified. System.Text.Json then writes them
    /// WITHOUT a "Z", and the browser's Date parser reads an offset-less date-time string as
    /// LOCAL time. On an IST machine that silently shifted every displayed timestamp 5h30m early.</para>
    ///
    /// <para>Stamping Kind=Utc on the way out makes the wire format state what the value actually
    /// is; the frontend then renders it in IST (see date-format.util.ts). Nothing about how
    /// timestamps are stored or compared changes - this is a serialization concern only.</para>
    /// </summary>
    public class UtcDateTimeJsonConverter : JsonConverter<DateTime>
    {
        public override DateTime Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options) =>
            reader.GetDateTime();

        public override void Write(Utf8JsonWriter writer, DateTime value, JsonSerializerOptions options)
        {
            var utc = value.Kind switch
            {
                DateTimeKind.Utc => value,
                DateTimeKind.Local => value.ToUniversalTime(),
                // Unspecified - straight off a DATETIME2 column, which this portal only ever
                // writes in UTC. Label it rather than convert it.
                _ => DateTime.SpecifyKind(value, DateTimeKind.Utc)
            };

            writer.WriteStringValue(utc);
        }
    }
}
