using System.Text.RegularExpressions;

namespace SubscriptionPortal.Core.Validation
{
    /// <summary>
    /// The portal sells into India, so a contact number is an Indian mobile: ten digits starting
    /// 6-9, optionally prefixed +91 / 91 / 0. Spaces and hyphens are tolerated anywhere between
    /// the digits, because "+91 98765 43210" is how people actually type it (and is what the
    /// Signup form shows as its placeholder).
    ///
    /// <para><see cref="Pattern"/> is duplicated verbatim on the frontend in
    /// core/validators/indian-mobile.validator.ts - keep the two in step, so a number that passes
    /// in the browser cannot then be rejected by the API.</para>
    /// </summary>
    public static class IndianMobile
    {
        public const string Pattern = @"^\s*(?:\+?91[\s-]?|0)?[6-9](?:[\s-]?\d){9}\s*$";

        public const string ErrorMessage =
            "Enter a valid 10-digit Indian mobile number, for example +91 98765 43210.";

        /// <summary>True when <paramref name="value"/> is a well-formed Indian mobile number.
        /// Blank is NOT valid here - whether the number is required at all is the caller's
        /// decision (it is currently optional at signup), so callers check for blank first.</summary>
        public static bool IsValid(string? value) =>
            !string.IsNullOrWhiteSpace(value) && Regex.IsMatch(value, Pattern);
    }
}
