import { formatDate } from '@angular/common';

/**
 * Indian Standard Time is a fixed +05:30 offset all year - India observes no daylight saving -
 * so a constant offset is correct here and avoids shipping a timezone database.
 *
 * The API sends timestamps as UTC with an explicit "Z" (see UtcDateTimeJsonConverter on the
 * backend). Pinning the offset here, rather than letting the browser pick, means the portal
 * shows the same IST clock time to every user regardless of their machine's timezone - which is
 * what people expect of an Indian business application.
 */
export const IST_OFFSET = '+0530';

const IST_LOCALE = 'en-IN';

/** 24 Oct 2026 */
export const IST_DATE_FORMAT = 'dd MMM yyyy';

/** 24 Oct 2026, 01:30 pm */
export const IST_DATE_TIME_FORMAT = 'dd MMM yyyy, hh:mm a';

/** Renders a UTC timestamp from the API as an IST date and time. */
export function formatIstDateTime(
  value: string | Date | null | undefined,
  fallback = '-'
): string {
  return value ? formatDate(value, IST_DATE_TIME_FORMAT, IST_LOCALE, IST_OFFSET) : fallback;
}

/** Renders a UTC timestamp from the API as an IST date, no time of day. */
export function formatIstDate(
  value: string | Date | null | undefined,
  fallback = '-'
): string {
  return value ? formatDate(value, IST_DATE_FORMAT, IST_LOCALE, IST_OFFSET) : fallback;
}
