=== NEW FILES ===
import { AbstractControl, ValidationErrors } from '@angular/forms';

/**
 * Ten digits starting 6-9, optionally prefixed +91 / 91 / 0, with spaces or hyphens allowed
 * between the digits - "+91 98765 43210" is how people actually type it, and is the Signup
 * form's own placeholder.
 *
 * Kept character-for-character identical to IndianMobile.Pattern on the backend
 * (SubscriptionPortal.Core/Validation/IndianMobile.cs). If you change one, change both -
 * otherwise a number accepted in the browser gets rejected by the API.
 */
export const INDIAN_MOBILE_PATTERN = /^\s*(?:\+?91[\s-]?|0)?[6-9](?:[\s-]?\d){9}\s*$/;

/**
 * Validates an Indian mobile number, treating blank as valid - presence is Validators.required's
 * job, and the field is currently optional at signup.
 */
export function indianMobileValidator(control: AbstractControl): ValidationErrors | null {
  const value = (control.value ?? '').toString();

  if (!value.trim()) {
    return null;
  }

  return INDIAN_MOBILE_PATTERN.test(value) ? null : { indianMobile: true };
}

