export const INDIAN_MOBILE_PATTERN = /^\s*(?:\+?91[\s-]?|0)?[6-9](?:[\s-]?\d){9}\s*$/;

/**
 * Validates an Indian mobile number, treating blank as valid - presence is Validators.required's
 * job, and the field is currently optional at signup.
 */
export function indianMobileValidator(control: AbstractControl): ValidationErrors | null {
  const value = (control.value ?? '').toString();

  if (!value.trim()) {
    return null;
  }

  return INDIAN_MOBILE_PATTERN.test(value) ? null : { indianMobile: true };
}

