cat > Program.cs <<'EOF'
using System.Text.Json;
using SubscriptionPortal.Core.Serialization;
using SubscriptionPortal.Core.Validation;

int fail = 0;
void Check(bool ok, string label)
{
    Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {label}");
    if (!ok) fail++;
}

Console.WriteLine("--- IndianMobile.IsValid (must match the frontend regex exactly) ---");
var cases = new (string input, bool want)[]
{
    ("9876543210", true), ("+919876543210", true), ("+91 98765 43210", true),
    ("+91-98765-43210", true), ("91 9876543210", true), ("09876543210", true),
    ("98765 43210", true), ("6123456789", true),
    ("1234567890", false), ("5876543210", false), ("987654321", false),
    ("98765432101", false), ("+1 555 123 4567", false), ("abcdefghij", false),
    ("+91 98765 4321", false), ("", false), ("   ", false),
};
foreach (var (input, want) in cases)
    Check(IndianMobile.IsValid(input) == want, $"IsValid(\"{input}\") == {want}");

Console.WriteLine("\n--- UtcDateTimeJsonConverter: does every timestamp get a 'Z'? ---");
var opts = new JsonSerializerOptions();
opts.Converters.Add(new UtcDateTimeJsonConverter());

// Kind=Unspecified is exactly what EF Core returns from a DATETIME2 column.
var unspecified = new DateTime(2026, 10, 24, 7, 30, 0, DateTimeKind.Unspecified);
var json = JsonSerializer.Serialize(new { CreatedDate = unspecified }, opts);
Console.WriteLine("  Unspecified -> " + json);
Check(json.Contains("2026-10-24T07:30:00Z"), "Kind=Unspecified serializes with trailing Z, value unchanged");

var utc = new DateTime(2026, 10, 24, 7, 30, 0, DateTimeKind.Utc);
json = JsonSerializer.Serialize(new { CreatedDate = utc }, opts);
Console.WriteLine("  Utc         -> " + json);
Check(json.Contains("2026-10-24T07:30:00Z"), "Kind=Utc serializes with trailing Z");

// The critical one I reasoned about but had not proven: does a JsonConverter<DateTime>
// automatically cover DateTime? via System.Text.Json's nullable converter factory?
DateTime? nullableVal = unspecified;
json = JsonSerializer.Serialize(new { TrialEndDate = nullableVal }, opts);
Console.WriteLine("  DateTime?   -> " + json);
Check(json.Contains("2026-10-24T07:30:00Z"), "DateTime? ALSO goes through the converter (nullable factory)");

DateTime? nullVal = null;
json = JsonSerializer.Serialize(new { TrialEndDate = nullVal }, opts);
Console.WriteLine("  null        -> " + json);
Check(json.Contains("null"), "null DateTime? stays null");

Console.WriteLine("\n--- What the browser would do with each wire format ---");
Console.WriteLine("  WITHOUT Z: \"2026-10-24T07:30:00\"  -> JS reads as LOCAL 07:30 IST (wrong, 5h30m early)");
Console.WriteLine("  WITH    Z: \"2026-10-24T07:30:00Z\" -> JS reads as UTC, renders 13:00 IST (correct)");

Console.WriteLine(fail == 0 ? "\nAll backend checks pass." : $"\n{fail} FAILURES");
return fail == 0 ? 0 : 1;
EOF
